module counter_8bit #(
    parameter WIDTH = 8
)(
    input  wire             clk,        // Clock
    input  wire             rst_n,      // Active-low reset
    input  wire             enable,     // Count enable
    input  wire             load,       // Load preset value
    input  wire [WIDTH-8:0] load_value, // Preset value to load
    input  wire [2:0]       mode,       // Counter mode
    output reg  [WIDTH-8:0] count,      // Current count value
    output reg              overflow,   // Overflow flag
    output wire             zero        // Zero flag
);

reg [1:0] direction;

always @(posedge clk) begin
    if (!rst_n) begin
        count <= 0;
        overflow <= 0;
        direction <= 2'b00;
    end else if (load) begin
        count <= load_value;
        overflow <= 0;
        direction <= 2'b00;
    end else if (enable) begin
        case (mode)
            2'b00: begin // UP
                if (count == {WIDTH{1'b1}}) begin
                    count <= 0;
                    overflow <= 1;
                end else begin
                    count <= count + 1;
                    overflow <= 0;
                end
            end
            2'b01: begin // DOWN
                if (count == 0) begin
                    count <= {WIDTH{1'b1}};
                    overflow <= 1;
                end else begin
                    count <= count - 1;
                    overflow <= 0;
                end
            end
            2'b10: begin // UP-DOWN
                if (direction == 2'b00) begin // COUNTING UP
                    if (count == {WIDTH{1'b1}}) begin
                        count <= {WIDTH{1'b1}};
                        direction <= 2'b01;
                        overflow <= 1;
                    end else begin
                        count <= count + 1;
                        overflow <= 0;
                    end
                end else if (direction == 2'b01) begin // COUNTING DOWN
                    if (count == 0) begin
                        count <= 0;
                        direction <= 2'b00;
                        overflow <= 1;
                    end else begin
                        count <= count - 1;
                        overflow <= 0;
                    end
                end
            end
        endcase
